def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.192.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.191.0"' not in init:
        sys.exit("ABORT: not at v3.191.0.")
    if "taxes_invoicing" not in data:
        sys.exit("ABORT: taxes_invoicing module not found in data file.")

    problems = _validate("SELL6", LESSONS_S6, QUESTIONS_S6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_S6))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — SELL6 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_S6)
    print(f"SELL 6 v3: {len(LESSONS_S6)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_S6):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["taxes_invoicing"]["lessons"] = LESSONS_S6
    data["taxes_invoicing"]["questions"] = bank
    data["taxes_invoicing"]["desc"] = ("Taxes, pricing governance, and invoicing preparation in ZhiftERP: the Nigerian VAT context — the 7.5% rate, the output liability flow, exempt classes, and the e-invoicing rules; Sales Taxes and Charges Templates — row types, account heads, the standard set, and accountant-only maintenance; item tax templates on mixed documents with per-line computation and the refusal rule; inclusive and exclusive pricing arithmetic with the one-posture-per-channel policy; discounts governance — the three instruments, their holders, the additional discount field, and the monthly read; and the watching reports — the trend read, the sales register, and the fifteen-minute five-check weekly habit feeding the monthly commercial review.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.191.0"', '"3.192.0"'))
    print("  data: SELLING 6 lessons + bank REPLACED (style v3, textbook manual register)")
    print("wrote __version__ -> 3.192.0")


if __name__ == "__main__":
    main()
